import sys
from html.parser import HTMLParser
from html import unescape
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.depth=0; self.in_result=False; self.in_a=False; self.in_p=False; self.href=''; self.title=''; self.desc=''; self.results=[]
    def handle_starttag(self,t,a):
        d=dict(a); c=d.get('class','')
        if t=='li' and 'b_algo' in c: self.in_result=True; self.depth=1; self.title=''; self.desc=''; self.href=''
        elif self.in_result:
            self.depth+=1
            if t=='a' and not self.in_a:
                self.in_a=True; self.href=unescape(d.get('href','')); self._buf=''
            if t=='p': self.in_p=True; self._pbuf=''
    def handle_endtag(self,t):
        if self.in_result:
            if t=='a' and self.in_a:
                self.title=' '.join(self._buf.split()); self.in_a=False
            if t=='p' and self.in_p:
                self.desc=' '.join(self._pbuf.split()); self.in_p=False
            self.depth-=1
            if self.depth==0:
                self.results.append((self.title,self.href,self.desc)); self.in_result=False
    def handle_data(self,d):
        if self.in_a: self._buf += ' '+d
        if self.in_p: self._pbuf += ' '+d
p=P()
try: p.feed(open(sys.argv[1], errors='ignore').read())
except Exception as e: print('ERR',e); raise SystemExit
for title, href, desc in p.results:
    print('TITLE:',title)
    print('LINK:',href)
    print('DESC:',desc[:400])
print('COUNT',len(p.results))
PY
done"

