 def handle_starttag(self,t,a):
  d=dict(a)
  if t=='a' and 'result__a' in d.get('class',''):
   self.in_a=True; self.href=unescape(d.get('href','')); self.buf=''
  if t in ('a','div') and 'result__snippet' in d.get('class',''):
   self.in_snip=True; self.buf=''
 def handle_endtag(self,t):
  if t=='a' and self.in_a:
   self.results.append(('TITLE', ' '.join(self.buf.split()), self.href)); self.in_a=False
  if t=='div' and self.in_snip:
   self.results.append(('DESC',' '.join(self.buf.split()),'')); self.in_snip=False
 def handle_data(self,d):
